import assert from "node:assert/strict";
import test from "node:test";
import { encodeWorkspace } from "../../../main/frontend/graph-explorer/workspace-format.ts";
import { parseWorkspacePayload, recoverWorkspacePayload } from "../../../main/frontend/graph-explorer/workspace.ts";
import { VIEW_MODES } from "../../../main/frontend/graph-explorer/explorer-types.ts";
import { readDisplayPreferences, SHOW_LABELS_STORAGE_KEY, SHOW_VALUES_STORAGE_KEY } from "../../../main/frontend/graph-explorer/explorer-config.ts";

const view=()=>({version:1,showValues:false,showAllEdgeLabels:true,viewMode:"table",selectedFacetValues:[["urn:p",["urn:a"]]],
  facetModes:[["urn:p","all"]],rangeDrafts:[["urn:p",{from:"1",to:"2"}]],
  labelPolicy:{languages:["nb"],properties:["urn:label"],languagesConfigured:true,propertiesConfigured:false},
  panels:{query:true,filters:false,navigator:true,history:false,inspector:true},focusedEdgeId:null});
const payload=(extra={})=>({graph:{nodes:[{id:"urn:a",label:"A",kind:"iri"}],edges:[],revision:0},transform:{x:0,y:0,k:1},
  query:"",endpointId:"repo",customUrl:"",provenanceBatches:[],namedGroups:[],selectedNodeIds:[],focusedNodeId:null,savedAt:null,...extra});

test("workspace view choices survive the compact workspace roundtrip",()=>{
  const raw=encodeWorkspace(payload({view:view()}));
  assert.deepEqual(parseWorkspacePayload(raw,{repositoryReferences:true}).view,view());
});

test("every view mode the page has survives a save",()=>{
  for(const viewMode of VIEW_MODES){
    const raw=encodeWorkspace(payload({view:{...view(),viewMode}}));
    assert.equal(parseWorkspacePayload(raw,{repositoryReferences:true}).view?.viewMode,viewMode);
  }
});

test("a view this version cannot read is left out; the graph still opens and recovers",()=>{
  const unreadable=[{...view(),version:2},{...view(),viewMode:"list"},{...view(),panels:{}},
    {...view(),labelPolicy:{...view().labelPolicy,languages:["not a tag"]}}];
  for(const candidate of unreadable){
    const raw=encodeWorkspace(payload({view:candidate}));
    const opened=parseWorkspacePayload(raw,{repositoryReferences:true});
    assert.ok(opened,`opens despite ${JSON.stringify(candidate).slice(0,60)}`);
    assert.equal(opened.view,undefined);
    assert.equal(opened.graph.nodes.length,1);
    assert.equal(recoverWorkspacePayload(raw)?.payload.graph.nodes.length,1);
  }
});

test("a named group none of whose nodes is in the graph is dropped when opened; an empty one stays",()=>{
  const raw=JSON.stringify(payload({namedGroups:[{id:"gone",name:"Gone",color:"red",nodeIds:["urn:missing"]},
    {id:"part",name:"Part",color:"blue",nodeIds:["urn:a","urn:missing"]},{id:"empty",name:"Empty",color:"green",nodeIds:[]}]}));
  assert.deepEqual(parseWorkspacePayload(raw,{repositoryReferences:true}).namedGroups.map(group=>[group.id,group.nodeIds]),
    [["part",["urn:a"]],["empty",[]]]);
});

test("old workspaces show the stored display preferences",()=>{
  const stored=new Map([[SHOW_VALUES_STORAGE_KEY,"true"],[SHOW_LABELS_STORAGE_KEY,"false"]]);
  assert.deepEqual(readDisplayPreferences({getItem:key=>stored.get(key)??null}),{showValues:true,showAllEdgeLabels:false});
  assert.deepEqual(readDisplayPreferences({getItem(){throw new Error("blocked");}}),{showValues:false,showAllEdgeLabels:false});
  assert.deepEqual(readDisplayPreferences(undefined),{showValues:false,showAllEdgeLabels:false});
});
